@CrossOrigin
@RestController
@RequestMapping("/EmployeeQuery")
public class EmployeeQueryRestController extends BaseSpringRestController {
	
	public EmployeeQueryRestController( EmployeeService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Employee using a UUID
     * @param		UUID employeeId
     * @return		Employee
     */    
    @GetMapping("/load")
    public Employee load( @RequestParam(required=true) UUID employeeId ) {
    	Employee entity = null;

    	try {  
    		entity = service.getEmployee( new EmployeeFetchOneSummary( employeeId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Employee using Id " + employeeId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Employee business objects
     * @return		Set<Employee>
     */
    @GetMapping("/")
    public List<Employee> loadAll() {                
    	List<Employee> employeeList = null;
        
    	try {
            // load the Employee
            employeeList = service.getAllEmployee();
            
            if ( employeeList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Employees" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Employees ", exc );
        	return null;
        }

        return employeeList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Employee employee = null;
    protected EmployeeService service = null;
    private static final Logger LOGGER = Logger.getLogger(EmployeeQueryRestController.class.getName());
    
}
